    console.log(numberArray);        // \u8FD4\u56DE [6] ...`,difficulty:"\u57FA\u7840"},{no:370,id:"javascript-0123",category:"JavaScript",topic:"\u51FD\u6570\u4E0E\u4F5C\u7528\u57DF",question:"\u4EC0\u4E48\u662F thunk \u51FD\u6570\uFF1F",answer:"thunk \u53EA\u662F\u4E00\u4E2A\u5EF6\u8FDF\u503C\u8BC4\u4F30\u7684\u51FD\u6570\u3002\u5B83\u4E0D\u63A5\u53D7\u4EFB\u4F55\u53C2\u6570\uFF0C\u4F46\u6BCF\u5F53\u60A8\u8C03\u7528 thunk \u65F6\u90FD\u4F1A\u7ED9\u51FA\u503C\u3002\u5373\uFF0C\u5B83\u7528\u4E8E\u73B0\u5728\u4E0D\u6267\u884C\uFF0C\u4F46\u4F1A\u5728\u5C06\u6765\u7684\u67D0\u4E2A\u65F6\u5019\u6267\u884C\u3002\u6211\u4EEC\u4E3E\u4E00\u4E2A\u540C\u6B65\u7684\u4F8B\u5B50\uFF0C```javascript\n      const add = (x, y) => x + y;\n\n      const thunk = () => add(2, 3);\n\n      thunk(); // 5\n      ```",difficulty:"\u57FA\u7840"},{no:371,id:"javascript-0124",category:"JavaScript",topic:"\u51FD\u6570\u4E0E\u4F5C\u7528\u57DF",question:"\u4EC0\u4E48\u662F\u4E00\u5143\u51FD\u6570\uFF1F",answer:"\u4E00\u5143\u51FD\u6570\uFF08\u4E5F\u79F0\u4E3A**\u4E00\u5143**\u51FD\u6570\uFF09\u662F\u4E00\u79CD**\u53EA\u63A5\u53D7\u4E00\u4E2A\u53C2\u6570**\u7684\u51FD\u6570\u3002\u672F\u8BED\u201C\u4E00\u5143\u201D\u4EC5\u6307\u51FD\u6570\u7684\u5143\u6570\uFF08arity\uFF09\u2014\u2014\u5B83\u63A5\u53D7\u7684\u53C2\u6570\u7684\u6570\u91CF\u3002\n\n    \u8BA9\u6211\u4EEC\u4E3E\u4E00\u4E2A\u4E00\u5143\u51FD\u6570\u7684\u4F8B\u5B50\uFF0C```javascript\n    const unaryFunction = (a) => console.log(a + 10); // This will add 10 to the input and log the result\n    unaryFunction(5); // Output: 15\n    ```\u5728\u8FD9\u4E2A\u4F8B\u5B50\u4E2D\uFF1A\n\n    -`unaryFunction`\u91C7\u7528\u5355\u4E2A\u53C2\u6570`a`\uFF0C\u4F7F\u5176\u6210\u4E3A\u4E00\u5143\u51FD\u6570\u3002\n    - \u5B83\u6267\u884C\u4E00\u4E2A\u7B80\u5355\u7684\u64CD\u4F5C\uFF1A\u5C06 10 \u6DFB\u52A0\u5230\u8F93\u5165\u5E76\u6253\u5370\u7ED3\u679C\u3002",difficulty:"\u57FA\u7840"},{no:372,id:"javascript-0125",category:"JavaScript",topic:"\u51FD\u6570\u4E0E\u4F5C\u7528\u57DF",question:"\u4EC0\u4E48\u662F\u533F\u540D\u51FD\u6570\uFF1F",answer:`\u533F\u540D\u51FD\u6570\u662F\u6CA1\u6709\u540D\u79F0\u7684\u51FD\u6570\uFF01\u533F\u540D\u51FD\u6570\u901A\u5E38\u5206\u914D\u7ED9\u53D8\u91CF\u540D\u6216\u7528\u4F5C\u56DE\u8C03\u51FD\u6570\u3002\u8BED\u6CD5\u5982\u4E0B\uFF0C\`\`\`javascript
